      console.log(level4Var); // ✅ Own scope
      console.log(level3Var); // ✅ Parent scope
      console.log(level2Var); // ✅ Grandparent scope
      console.log(globalVar); // ✅ Global scope
    }

    level4();
  }

  level3();
}

level2();
