// Example usage:
const array1 = [1, 2, 3, 4];

console.log(array1.customFill(0, 2, 4)); // Output: [1, 2, 0, 0]
console.log(array1.customFill(5, 1));    // Output: [1, 5, 5, 5]
console.log(array1.customFill(6));       // Output: [6, 6, 6, 6]
