}

// ✅ GOOD: Use indices (O(1) space)
for (let i = 0; i <= s.length - k; i++) {
  process(s, i, i + k);  // Pass indices only
}

// ✅ GOOD: Reuse Set (O(k) space max)
const charSet = new Set();  // Single set for entire algorithm
