## 6️⃣ Real-World Examples

### React Implementation with Hooks

```javascript
import { useState, useEffect, useRef, useCallback } from 'react';

// Custom hook for cursor tracking
const useCursorTracking = (options = {}) => {
  const {
    throttleMs = 16,
    enableHistory = false,
    maxHistorySize = 100
  } = options;

  const [position, setPosition] = useState({ x: 0, y: 0 });
  const historyRef = useRef([]);
  const lastUpdateRef = useRef(0);

  const handleMouseMove = useCallback((event) => {
    const now = Date.now();

    // Throttle updates
    if (now - lastUpdateRef.current < throttleMs) {
      return;
    }

    lastUpdateRef.current = now;

    const newPosition = {
      x: event.clientX,
      y: event.clientY,
      pageX: event.pageX,
      pageY: event.pageY,
      timestamp: now
    };

    setPosition(newPosition);

    // Add to history if enabled
    if (enableHistory) {
      historyRef.current.push(newPosition);
      if (historyRef.current.length > maxHistorySize) {
        historyRef.current.shift();
      }
    }
  }, [throttleMs, enableHistory, maxHistorySize]);

  useEffect(() => {
    document.addEventListener('mousemove', handleMouseMove);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
    };
  }, [handleMouseMove]);

  return {
    position,
    history: historyRef.current
  };
};

// Component using the hook
const CursorDisplay = () => {
  const { position } = useCursorTracking({ throttleMs: 16 });

  return (
    <div style={{
      position: 'fixed',
      top: 10,
      left: 10,
      background: 'rgba(0,0,0,0.8)',
      color: 'white',
      padding: '10px 15px',
      borderRadius: 5,
      fontFamily: 'monospace',
      pointerEvents: 'none',
      zIndex: 9999
    }}>
      <div>X: {position.x}</div>
      <div>Y: {position.y}</div>
    </div>
  );
};

// Custom cursor component
const CustomCursor = () => {
  const { position } = useCursorTracking({ throttleMs: 8 });
  const [isHovering, setIsHovering] = useState(false);

  useEffect(() => {
    // Hide default cursor
    document.body.style.cursor = 'none';

    return () => {
      document.body.style.cursor = 'auto';
    };
  }, []);

  // Check if hovering over interactive elements
  useEffect(() => {
    const checkHover = () => {
      const elements = document.elementsFromPoint(position.x, position.y);
      const interactive = elements.some(el => 
        el.tagName === 'A' || 
        el.tagName === 'BUTTON' || 
        el.onclick !== null
      );
      setIsHovering(interactive);
    };

    checkHover();
  }, [position]);

  return (
    <div style={{
      position: 'fixed',
      left: position.x,
      top: position.y,
      width: isHovering ? 40 : 20,
      height: isHovering ? 40 : 20,
      borderRadius: '50%',
      border: '2px solid #00ffff',
      transform: 'translate(-50%, -50%)',
      pointerEvents: 'none',
      zIndex: 999999,
      transition: 'width 0.2s, height 0.2s',
      mixBlendMode: 'difference'
    }} />
  );
};

export { useCursorTracking, CursorDisplay, CustomCursor };
```

